94. /// A type that represents a virtual memory space.
95. #[cfg_attr(verus_keep_ghost, verus_verify)]
96. pub struct Vmem {
97.     /// Underlying page directory.
98.     pgdir: PageDirectory<PageDirectoryStorage>,
99.     /// List of kernel page tables.
100.     kernel_page_tables: LinkedList<Rc<RefCell<(PageTableAddress, PageTable<PageTableStorage>)>>>,
101.     /// List of kernel pages mapped in the virtual address space.
102.     /// NOTE: this currently excludes kernel pages that are identity mapped.
103.     kernel_pages: LinkedList<Rc<RefCell<KernelPage>>>,
104.     /// List of user page tables.
105.     user_page_tables: LinkedList<(PageTableAddress, PageTable<PageTableStorage>)>,
106.     /// Ghost abstraction of this address space (spec-only; see `vmem.spec.rs`).
