112. impl Vmem {
113.     /// Initializes a new virtual memory space.
114.     #[verus_spec(ret =>
115.         ensures
116.             match ret {
117.                 Ok(v) => {
118.                     &&& v@.user == Map::<nat, UserPageView>::empty()
119.                     &&& v.inv()
120.                 },
121.                 Err(_) => true,
122.             },
123.     )]
124.     #[cfg_attr(verus_keep_ghost, verus_verify(external_body))]
125.     pub fn new(
126.         mut kernel_pages: LinkedList<KernelPage>,
127.         mut kernel_page_tables: LinkedList<(PageTableAddress, PageTable<PageTableStorage>)>,
128.     ) -> Result<Self, Error> {
129.         trace!("kernel_pages.len()={}", kernel_pages.len());
130. 
131.         // Create a clean page directory.
132.         let mut pgdir: PageDirectory<PageDirectoryStorage> =
133.             // SAFETY: this constructor is only used during early single-threaded init;
134.             // BSS is zero-initialized, so assume_init_mut() is sound for integer arrays.
135.             PageDirectory::new(PageDirectoryStorage::Bss(unsafe {
136.                 PAGE_TABLE_ALLOCATOR
137.                     .alloc_as::<[PteWord; PAGE_TABLE_LENGTH]>()
138.                     .map_err(|e| {
139.                         error!("Vmem::new(): page directory allocation failed: {}", e);
140.                         Error::new(ErrorCode::OutOfMemory, "BSS page directory allocation failed")
141.                     })?
142.                     .assume_init_mut()
143.             }));
144. 
145.         // Map and store root page tables.
146.         let mut kpage_tables: LinkedList<
147.             Rc<RefCell<(PageTableAddress, PageTable<PageTableStorage>)>>,
148.         > = LinkedList::new();
149.         while let Some((vaddr, page_table)) = kernel_page_tables.pop_front() {
150.             let page_table_address: FrameAddress = page_table.physical_address()?;
151.             // FIXME: do not be so open about permissions.
152.             pgdir.map(vaddr, page_table_address, false, AccessPermission::RDWR)?;
153.             kpage_tables.push_back(Rc::new(RefCell::new((vaddr, page_table))));
154.         }
155. 
156.         // Register the kernel page directory for lazy identity mapping and set CR3.
157.         {
158.             use crate::hal::mem::PageDirectoryAddress;
